# Use pdfbox via jshell or small java to inspect lines
cd /tmp && cat > PdfInspect.java << 'EOF'
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import org.apache.pdfbox.util.Matrix;
import org.apache.pdfbox.pdmodel.font.PDFont;
import java.awt.geom.Point2D;
import java.io.File;
import java.io.IOException;
import java.util.*;

public class PdfInspect {
  static class LineCollector extends PDFGraphicsStreamEngine {
    List<String> lines = new ArrayList<>();
    int pathOps=0, strokeOps=0, fillOps=0, textChars=0;
    protected LineCollector(PDPage page){super(page);} 
    public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) throws IOException { pathOps++; lines.add(String.format(Locale.US,"RECT %.1f,%.1f %.1f,%.1f", p0.getX(),p0.getY(),p2.getX(),p2.getY())); }
    public void clip(int w) throws IOException {}
    public void moveTo(float x,float y) throws IOException { pathOps++; }
    public void lineTo(float x,float y) throws IOException { pathOps++; lines.add(String.format(Locale.US,"LINE to %.1f,%.1f",x,y)); }
    public void curveTo(float x1,float y1,float x2,float y2,float x3,float y3) throws IOException { pathOps++; }
    public Point2D getCurrentPoint() throws IOException { return new Point2D.Float(0,0); }
    public void closePath() throws IOException {}
    public void endPath() throws IOException {}
    public void strokePath() throws IOException { strokeOps++; }
    public void fillPath(int w) throws IOException { fillOps++; }
    public void fillAndStrokePath(int w) throws IOException { fillOps++; strokeOps++; }
    public void shadingFill(COSName n) throws IOException {}
    public void drawImage(PDImage pdImage) throws IOException {}
    public void showGlyph(Matrix t, PDFont f, int c, Vector d) throws IOException { textChars++; super.showGlyph(t,f,c,d); }
  }
  public static void main(String[] a) throws Exception {
    String[] files = a;
    for (String fp: files) {
      try (PDDocument doc = Loader.loadPDF(new File(fp))) {
        PDPage page = doc.getPage(0);
        LineCollector c = new LineCollector(page);
        c.processPage(page);
        System.out.println("=== "+fp+" pages="+doc.getNumberOfPages()+" pathOps="+c.pathOps+" strokes="+c.strokeOps+" fills="+c.fillOps+" textChars="+c.textChars+" sampleLines="+Math.min(5,c.lines.size()));
        for (int i=0;i<Math.min(8,c.lines.size());i++) System.out.println("  "+c.lines.get(i));
      }
    }
  }
}
