import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import org.apache.pdfbox.util.Matrix;
import org.apache.pdfbox.pdmodel.font.PDFont;
import org.apache.pdfbox.text.PDFTextStripper;
import org.apache.pdfbox.text.TextPosition;
import java.awt.geom.Point2D;
import java.io.File;
import java.io.IOException;
import java.util.*;

public class PdfInspect {
  static class Stats extends PDFGraphicsStreamEngine {
    int pathOps=0, strokeOps=0, fillOps=0, rects=0, hLines=0, vLines=0;
    double lastX, lastY; boolean hasMove;
    protected Stats(PDPage page){super(page);} 
    public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) throws IOException { rects++; pathOps++; }
    public void clip(int w) throws IOException {}
    public void moveTo(float x,float y) throws IOException { lastX=x; lastY=y; hasMove=true; pathOps++; }
    public void lineTo(float x,float y) throws IOException {
      pathOps++;
      if (hasMove) {
        if (Math.abs(y-lastY)<1.0 && Math.abs(x-lastX)>5) hLines++;
        if (Math.abs(x-lastX)<1.0 && Math.abs(y-lastY)>5) vLines++;
      }
      lastX=x; lastY=y;
    }
    public void curveTo(float x1,float y1,float x2,float y2,float x3,float y3) throws IOException { pathOps++; }
    public Point2D getCurrentPoint() throws IOException { return new Point2D.Float((float)lastX,(float)lastY); }
    public void closePath() throws IOException {}
    public void endPath() throws IOException {}
    public void strokePath() throws IOException { strokeOps++; }
    public void fillPath(int w) throws IOException { fillOps++; }
    public void fillAndStrokePath(int w) throws IOException { fillOps++; strokeOps++; }
    public void shadingFill(COSName n) throws IOException {}
    public void drawImage(PDImage pdImage) throws IOException {}
  }
  public static void main(String[] a) throws Exception {
    File root = new File("/app/src/test/resources/pdf-samples-latest");
    List<File> pdfs = new ArrayList<>();
    for (File bank: root.listFiles()) if (bank.isDirectory()) for (File f: bank.listFiles()) if (f.getName().endsWith(".pdf")) pdfs.add(f);
    Collections.sort(pdfs);
    for (File fp: pdfs) {
      try (PDDocument doc = Loader.loadPDF(fp)) {
        PDPage page = doc.getPage(0);
        Stats c = new Stats(page);
        try { c.processPage(page); } catch (Exception e) {}
        String kind;
        if (c.hLines>20 && c.vLines>10) kind="BORDERED";
        else if (c.rects>15 || (c.hLines>10 && c.vLines<5)) kind="BOX_GUIDED";
        else kind="TEXT_ALIGNED";
        System.out.printf(Locale.US, "%s\t%s\th=%d v=%d r=%d s=%d f=%d pages=%d%n", fp.getParentFile().getName()+"/"+fp.getName(), kind, c.hLines, c.vLines, c.rects, c.strokeOps, c.fillOps, doc.getNumberOfPages());
      } catch (Exception e) {
        System.out.println(fp+ " ERR "+e.getMessage());
      }
    }
  }
}
