import java.util.Objects;

@Service
@Slf4j
public class RequestLogServiceImpl implements RequestLogService {
    private IMetaDataService metaDataService;
    private StorageServiceFactory storageServiceFactory;
    private CloudStorageProperties cloudStorageProperties;
    private IRequestLogRepository requestLogDataRepository;
    private IRequestPayloadLogRepository requestPayloadLogRepository;
    private IRequestDocumentLogRepository requestDocumentLogRepository;
    private IRequestAccountLogRepository requestAccountLogRepository;

    @Setter(onMethod_ = @Autowired)
    public IStatementUploadRequestLogRepository requestLogRepository;

    @Setter(onMethod_ = @Autowired)
    public IFinancialDocumentRepository documentRepository;

    @Autowired
    public void setMetaDataService(IMetaDataService metaDataService) {
        this.metaDataService = metaDataService;
    }

    @Autowired
    public void setStorageServiceFactory(StorageServiceFactory storageServiceFactory) {
        this.storageServiceFactory = storageServiceFactory;
    }

    @Autowired
    public void setCloudStorageProperties(CloudStorageProperties cloudStorageProperties) {
        this.cloudStorageProperties = cloudStorageProperties;
    }

    @Autowired
    public void setRequestLogRepository(IRequestLogRepository requestLogRepository) {
        this.requestLogDataRepository = requestLogRepository;
    }

    @Autowired
    public void setRequestPayloadLogRepository(IRequestPayloadLogRepository requestPayloadLogRepository) {
        this.requestPayloadLogRepository = requestPayloadLogRepository;
    }

    @Autowired
    public void setRequestDocumentLogRepository(IRequestDocumentLogRepository requestDocumentLogRepository) {
        this.requestDocumentLogRepository = requestDocumentLogRepository;
    }

    @Autowired
    public void setRequestAccountLogRepository(IRequestAccountLogRepository requestAccountLogRepository) {
        this.requestAccountLogRepository = requestAccountLogRepository;
    }

    @Override
    public void saveDocumentsInfo(List<BankStatementVO> statements) {

        if (null != statements && !statements.isEmpty()) {
            // Save documents info
            for (BankStatementVO bankStatementVO : statements) {
                //save request document details to the requestDocumentLog
                saveRequestDocumentLogData(bankStatementVO, FlowName.BANK_ACCOUNT.name(), SubFlowName.UPLOAD_STATEMENT.name(), RequestStatus.FILE_UPLOAD_TO_GCP_BUCKET_STARTED.name());

                FinancialDocumentEntity document = getFinancialDocumentEntity(bankStatementVO);

                //extract file meta data
                FileMetaDataDetails fileMetaDataDetails = metaDataService.extractFileMetaData(bankStatementVO.getDecryptedFile(), null);
                if(Objects.nonNull(fileMetaDataDetails))
                    document.setFileMetaData(fileMetaDataDetails.getMetaData());

                //upload file to the cloud storage bucket or local based on the property configuration
                try{
                    StorageService storageService = storageServiceFactory.createStorageService();
                    String storageFilePath = storageService.uploadFile(bankStatementVO.getDecryptedFile(), LoggingPropertiesUtil.getValueFromMDC("clientId"),
                            bankStatementVO.getBank());
                    document.setStorageBucketPath(storageFilePath);

                    //save request document details to the requestDocumentLog
                    saveRequestDocumentLogData(bankStatementVO, FlowName.BANK_ACCOUNT.name(), SubFlowName.UPLOAD_STATEMENT.name(), RequestStatus.FILE_UPLOAD_TO_GCP_BUCKET_COMPLETED.name());
                }catch (Exception e){
                    log.error(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog(RequestStatus.FAILED.name(), "Something went wrong while saving document info", ExceptionDetails.exceptionDetails(e.getMessage()))));
                    //save request document details to the requestDocumentLog
                    saveRequestDocumentErrorLogData(bankStatementVO, JsonUtil.getJsonStringFromObject(ExceptionDetails.exceptionDetails(e.getMessage())), FlowName.BANK_ACCOUNT.name(), SubFlowName.UPLOAD_STATEMENT.name(), RequestStatus.FILE_UPLOAD_TO_GCP_BUCKET_FAILED.name());
                }
                document.setFileStorageCloud(cloudStorageProperties.getProvider());
                documentRepository.save(document);
            }
        }
    }

    private static FinancialDocumentEntity getFinancialDocumentEntity(BankStatementVO bankStatementVO) {
        FinancialDocumentEntity document = new FinancialDocumentEntity();
        document.setClientId(LoggingPropertiesUtil.getValueFromMDC("clientId"));
        document.setBusinessUserId(LoggingPropertiesUtil.getValueFromMDC("businessUserId"));
        document.setReferenceId(LoggingPropertiesUtil.getValueFromMDC("referenceId"));
        document.setFileId(bankStatementVO.getFileId());
        document.setFileName(bankStatementVO.getOriginalFileName());
        document.setFileContentType("application/pdf");
        document.setFileExtension(FilenameUtils.getExtension(bankStatementVO.getOriginalFileName()));
        document.setFileStorageCloud(FileStorageCloud.GCP.name());
        document.setBank(bankStatementVO.getBank());
        document.setAccountType(bankStatementVO.getAccountType());
        return document;
    }

    @Override
    public void saveRequestLogData(String flowName, String subFlowName) {
        RequestLogEntity requestLogEntity = new RequestLogEntity(flowName, subFlowName);
        requestLogDataRepository.save(requestLogEntity);
    }

    @Override
    public void saveRequestPayloadLog(BankStatementRequest request){
        List<RequestPayloadLog> requestPayloadLogList = new ArrayList<>();
        if(!CollectionUtils.isEmpty(request.getStatement())) {
            for(StatementDTO statementDTO : request.getStatement()){
                RequestPayloadLog requestPayloadLog = new RequestPayloadLog(statementDTO.getBank(), statementDTO.getBankStmt().size());
                requestPayloadLogList.add(requestPayloadLog);
            }
        }

        if(!CollectionUtils.isEmpty(requestPayloadLogList)) {
            String jsonPayload = JsonUtil.getJsonStringFromObject(requestPayloadLogList);
            RequestPayloadLogEntity requestPayloadLogEntity = new RequestPayloadLogEntity(jsonPayload);
            requestPayloadLogRepository.save(requestPayloadLogEntity);
        }
    }

    @Override
    public void updateRequestErrorLogData(String status, String errorStatus, String errorMessage){
        RequestLogEntity requestLogEntity = requestLogDataRepository.findByClientIdAndJobId(LoggingPropertiesUtil.getValueFromMDC("clientId"),
                LoggingPropertiesUtil.getValueFromMDC("jobId"));
        if(Objects.nonNull(requestLogEntity)) {
            requestLogEntity.setStatus(status);
            requestLogEntity.setErrorStatus(errorStatus);
            requestLogEntity.setErrorMessage(errorMessage);
            requestLogEntity.setEndTime(System.currentTimeMillis());

            long totalTime = System.currentTimeMillis() - requestLogEntity.getStartTime();
            requestLogEntity.setTotalTime(totalTime);
            requestLogDataRepository.save(requestLogEntity);
        }
    }

    @Override
    public void updateRequestLogData(String status){
        RequestLogEntity requestLogEntity = requestLogDataRepository.findByClientIdAndJobId(LoggingPropertiesUtil.getValueFromMDC("clientId"),
                LoggingPropertiesUtil.getValueFromMDC("jobId"));
        if(Objects.nonNull(requestLogEntity)) {
            requestLogEntity.setStatus(status);
            requestLogEntity.setEndTime(System.currentTimeMillis());
            long totalTime = System.currentTimeMillis() - requestLogEntity.getStartTime();
            requestLogEntity.setTotalTime(totalTime);
            requestLogDataRepository.save(requestLogEntity);
        }
    }

    @Override
    public void saveRequestDocumentLogData(BankStatementVO bankStatementVO, String flowName, String subFlowName, String status){
        RequestDocumentLogEntity documentLogEntity = new RequestDocumentLogEntity(bankStatementVO, flowName, subFlowName, status);
        requestDocumentLogRepository.save(documentLogEntity);

    }

    @Override
    public void saveRequestDocumentErrorLogData(BankStatementVO bankStatementVO, String errorMessage, String flowName, String subFlowName, String status){
        RequestDocumentLogEntity documentLogEntity = new RequestDocumentLogEntity(bankStatementVO, errorMessage, flowName, subFlowName, status);

