package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import lombok.Data;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import org.apache.pdfbox.util.Matrix;
import org.apache.pdfbox.pdmodel.font.PDFont;

import java.awt.geom.Point2D;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

/**
 * Collects vector geometry (lines/rects) from a PDF page in inches, top-left origin.
 */
public final class NativePdfGeometry {

    public static final float POINTS_PER_INCH = 72.0f;

    private NativePdfGeometry() {
    }

    @Data
    public static class LineSegment {
        private final float x1;
        private final float y1;
        private final float x2;
        private final float y2;

        public boolean isHorizontal(float tol) {
            return Math.abs(y1 - y2) <= tol && Math.abs(x1 - x2) > tol;
        }

        public boolean isVertical(float tol) {
            return Math.abs(x1 - x2) <= tol && Math.abs(y1 - y2) > tol;
        }

        public float minX() {
            return Math.min(x1, x2);
        }

        public float maxX() {
            return Math.max(x1, x2);
        }

        public float minY() {
            return Math.min(y1, y2);
        }

        public float maxY() {
            return Math.max(y1, y2);
        }

        public float length() {
            float dx = x2 - x1;
            float dy = y2 - y1;
            return (float) Math.sqrt(dx * dx + dy * dy);
        }
    }

    @Data
    public static class Rect {
        private final float x1;
        private final float y1;
        private final float x2;
        private final float y2;

        public float width() {
            return Math.max(0f, x2 - x1);
        }

        public float height() {
            return Math.max(0f, y2 - y1);
        }

        public boolean contains(float x, float y, float pad) {
            return x >= x1 - pad && x <= x2 + pad && y >= y1 - pad && y <= y2 + pad;
        }
    }

    @Data
    public static class PageGeometry {
        private final float pageWidthInches;
        private final float pageHeightInches;
        private final List<LineSegment> lines = new ArrayList<>();
        private final List<Rect> rectangles = new ArrayList<>();
        private int strokeOps;
        private int fillOps;
    }

    public static PageGeometry collect(PDPage page) throws IOException {
        float pageHeightPts = page.getCropBox().getHeight();
        float pageWidthPts = page.getCropBox().getWidth();
        PageGeometry geometry = new PageGeometry(pageWidthPts / POINTS_PER_INCH, pageHeightPts / POINTS_PER_INCH);
        GeometryEngine engine = new GeometryEngine(page, pageHeightPts, geometry);
        engine.processPage(page);
        return geometry;
    }

    private static class GeometryEngine extends PDFGraphicsStreamEngine {
        private final float pageHeightPts;
        private final PageGeometry geometry;
        private float lastX;
        private float lastY;
        private boolean hasPoint;

        protected GeometryEngine(PDPage page, float pageHeightPts, PageGeometry geometry) {
            super(page);
            this.pageHeightPts = pageHeightPts;
            this.geometry = geometry;
        }

        private float toX(float xPts) {
            return xPts / POINTS_PER_INCH;
        }

        private float toY(float yPts) {
            return (pageHeightPts - yPts) / POINTS_PER_INCH;
        }

        @Override
        public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
            float minX = (float) Math.min(Math.min(p0.getX(), p1.getX()), Math.min(p2.getX(), p3.getX()));
            float maxX = (float) Math.max(Math.max(p0.getX(), p1.getX()), Math.max(p2.getX(), p3.getX()));
            float minYPts = (float) Math.min(Math.min(p0.getY(), p1.getY()), Math.min(p2.getY(), p3.getY()));
            float maxYPts = (float) Math.max(Math.max(p0.getY(), p1.getY()), Math.max(p2.getY(), p3.getY()));
            float yTop = toY(maxYPts);
            float yBottom = toY(minYPts);
            geometry.getRectangles().add(new Rect(toX(minX), Math.min(yTop, yBottom), toX(maxX), Math.max(yTop, yBottom)));
        }

        @Override
        public void clip(int windingRule) {
        }

        @Override
        public void moveTo(float x, float y) {
            lastX = x;
            lastY = y;
            hasPoint = true;
        }

        @Override
        public void lineTo(float x, float y) {
            if (hasPoint) {
                geometry.getLines().add(new LineSegment(toX(lastX), toY(lastY), toX(x), toY(y)));
            }
            lastX = x;
            lastY = y;
            hasPoint = true;
        }

        @Override
        public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) {
            lastX = x3;
            lastY = y3;
            hasPoint = true;
        }

        @Override
        public Point2D getCurrentPoint() {
            return new Point2D.Float(lastX, lastY);
        }

        @Override
        public void closePath() {
        }

        @Override
        public void endPath() {
            hasPoint = false;
        }

        @Override
        public void strokePath() {
            geometry.setStrokeOps(geometry.getStrokeOps() + 1);
            hasPoint = false;
        }

        @Override
        public void fillPath(int windingRule) {
            geometry.setFillOps(geometry.getFillOps() + 1);
            hasPoint = false;
        }

        @Override
        public void fillAndStrokePath(int windingRule) {
            geometry.setFillOps(geometry.getFillOps() + 1);
            geometry.setStrokeOps(geometry.getStrokeOps() + 1);
            hasPoint = false;
        }

        @Override
        public void shadingFill(COSName shadingName) {
        }

        @Override
        public void drawImage(PDImage pdImage) {
        }

        @Override
        protected void showGlyph(Matrix textRenderingMatrix, PDFont font, int code, Vector displacement) throws IOException {
            super.showGlyph(textRenderingMatrix, font, code, displacement);
        }
    }
}

