package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.text.PDFTextStripper;
import org.apache.pdfbox.text.TextPosition;
import org.springframework.stereotype.Component;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Extracts page-level words with inch coordinates (top-left origin) from electronic PDFs.
 */
@Component
@Slf4j
public class NativeWordExtractor {

    private static final float POINTS_PER_INCH = 72.0f;

    public List<PageWords> extract(File pdfFile) throws IOException {
        List<PageWords> pages = new ArrayList<>();
        try (PDDocument document = Loader.loadPDF(pdfFile)) {
            for (int pageIndex = 0; pageIndex < document.getNumberOfPages(); pageIndex++) {
                PDPage page = document.getPage(pageIndex);
                PDRectangle cropBox = page.getCropBox();
                float pageHeightPts = cropBox.getHeight();
                WordStripper stripper = new WordStripper(pageHeightPts);
                stripper.setSortByPosition(true);
                stripper.setStartPage(pageIndex + 1);
                stripper.setEndPage(pageIndex + 1);
                stripper.getText(document);

                PageWords pageWords = new PageWords();
                pageWords.setPageNumber(pageIndex + 1);
                pageWords.setWidth(cropBox.getWidth() / POINTS_PER_INCH);
                pageWords.setHeight(pageHeightPts / POINTS_PER_INCH);
                pageWords.setWords(stripper.getWords(pageIndex + 1));
                pages.add(pageWords);
            }
        }
        return pages;
    }

    public static class PageWords {
        private int pageNumber;
        private float width;
        private float height;
        private List<Word> words = new ArrayList<>();

        public int getPageNumber() {
            return pageNumber;
        }

        public void setPageNumber(int pageNumber) {
            this.pageNumber = pageNumber;
        }

        public float getWidth() {
            return width;
        }

        public void setWidth(float width) {
            this.width = width;
        }

        public float getHeight() {
            return height;
        }

        public void setHeight(float height) {
            this.height = height;
        }

        public List<Word> getWords() {
            return words;
        }

        public void setWords(List<Word> words) {
            this.words = words;
        }
    }

    private static class WordStripper extends PDFTextStripper {
        private final float pageHeightPts;
        private final List<TextPosition> positions = new ArrayList<>();

        WordStripper(float pageHeightPts) throws IOException {
            super();
            this.pageHeightPts = pageHeightPts;
        }

        @Override
        protected void writeString(String text, List<TextPosition> textPositions) {
            if (textPositions != null) {
                positions.addAll(textPositions);
            }
        }

        List<Word> getWords(int pageNumber) {
            List<Word> words = new ArrayList<>();
            if (positions.isEmpty()) {
                return words;
            }

            StringBuilder current = new StringBuilder();
            float minX = 0, minY = 0, maxX = 0, maxY = 0;
            boolean building = false;
            int wordIndex = 1;

            for (TextPosition tp : positions) {
                String unicode = tp.getUnicode();
                if (unicode == null || unicode.isEmpty()) {
                    continue;
                }
                if (Character.isWhitespace(unicode.charAt(0))) {
                    if (building) {
                        words.add(toWord(current.toString(), minX, minY, maxX, maxY, pageNumber, wordIndex++));
                        current.setLength(0);
                        building = false;
                    }
                    continue;
                }

                float x1 = tp.getXDirAdj() / POINTS_PER_INCH;
                float width = tp.getWidthDirAdj() / POINTS_PER_INCH;
                float height = tp.getHeightDir() / POINTS_PER_INCH;
                float yTop = (pageHeightPts - tp.getYDirAdj()) / POINTS_PER_INCH;
                float yBottom = yTop + height;
                float x2 = x1 + width;

                if (!building) {
                    current.append(unicode);
                    minX = x1;
                    maxX = x2;
                    minY = yTop;
                    maxY = yBottom;
                    building = true;
                } else {
                    // Split when large horizontal gap
                    if (x1 - maxX > Math.max(0.08f, (maxX - minX) * 0.35f)) {
                        words.add(toWord(current.toString(), minX, minY, maxX, maxY, pageNumber, wordIndex++));
                        current.setLength(0);
                        current.append(unicode);
                        minX = x1;
                        maxX = x2;
                        minY = yTop;
                        maxY = yBottom;
                    } else {
                        current.append(unicode);
                        minX = Math.min(minX, x1);
                        maxX = Math.max(maxX, x2);
                        minY = Math.min(minY, yTop);
                        maxY = Math.max(maxY, yBottom);
                    }
                }
            }
            if (building) {
                words.add(toWord(current.toString(), minX, minY, maxX, maxY, pageNumber, wordIndex));
            }
            positions.clear();
            return words;
        }

        private Word toWord(String content, float x1, float y1, float x2, float y2, int pageNumber, int wordIndex) {
            Word word = new Word();
            word.setContent(content);
            word.setX1(x1);
            word.setY1(y1);
            word.setX2(x2);
            word.setY2(y1);
            word.setX3(x2);
            word.setY3(y2);
            word.setX4(x1);
            word.setY4(y2);
            word.setWidth(Math.max(0f, x2 - x1));
            word.setHeight(Math.max(0f, y2 - y1));
            word.setPageNumber(pageNumber);
            word.setPageIndex(pageNumber);
            word.setWordIndex(wordIndex);
            return word;
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;

import java.util.*;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Shared helpers for building DocumentExtraction Table models from words + grid bounds.
 */
final class NativeTableBuilder {

    private static final Pattern DATE_LIKE = Pattern.compile(
            ".*(\\d{1,2}[-/]\\d{1,2}[-/]\\d{2,4}|\\d{1,2}[-/][A-Za-z]{3}[-/]\\d{2,4}|\\d{1,2}\\s+[A-Za-z]{3}\\s+\\d{2,4}).*"
    );

    private NativeTableBuilder() {
    }

    static Table buildTable(int pageNumber, List<Float> colBounds, List<Float> rowBounds, List<Word> words) {
        if (colBounds == null || rowBounds == null || colBounds.size() < 2 || rowBounds.size() < 2) {
            return null;
        }

        int cols = colBounds.size() - 1;
        int rows = rowBounds.size() - 1;
        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();

        for (int r = 0; r < rows; r++) {
            float y1 = rowBounds.get(r);
            float y2 = rowBounds.get(r + 1);
            Map<Integer, TableCell> row = new LinkedHashMap<>();
            for (int c = 0; c < cols; c++) {
                float x1 = colBounds.get(c);
                float x2 = colBounds.get(c + 1);
                TableCell cell = new TableCell();
                cell.setRowindex(r);
                cell.setColindex(c);
                cell.setColspan(1);
                cell.setRowspan(1);
                cell.setX1(x1);
                cell.setY1(y1);
                cell.setX2(x2);
                cell.setY2(y1);
                cell.setX3(x2);
                cell.setY3(y2);
                cell.setX4(x1);
                cell.setY4(y2);
                cell.setWords(new ArrayList<>());
                row.put(c, cell);
            }
            cells.put(r, row);
        }

        for (Word word : words) {
            if (word == null || word.getContent() == null || word.getContent().isBlank()) {
                continue;
            }
            float mx = midpointX(word);
            float my = midpointY(word);
            int col = findBucket(colBounds, mx);
            int row = findBucket(rowBounds, my);
            if (col < 0 || row < 0) {
                continue;
            }
            cells.get(row).get(col).getWords().add(word);
        }

        // Drop completely empty trailing/leading rows that have no content
        List<Integer> nonEmptyRows = cells.entrySet().stream()
                .filter(e -> e.getValue().values().stream().anyMatch(c -> c.getWords() != null && !c.getWords().isEmpty()))
                .map(Map.Entry::getKey)
                .sorted()
                .collect(Collectors.toList());
        if (nonEmptyRows.isEmpty()) {
            return null;
        }

        Map<Integer, Map<Integer, TableCell>> compacted = new LinkedHashMap<>();
        int newRow = 0;
        for (Integer oldRow : nonEmptyRows) {
            Map<Integer, TableCell> row = cells.get(oldRow);
            Map<Integer, TableCell> newMap = new LinkedHashMap<>();
            for (Map.Entry<Integer, TableCell> ce : row.entrySet()) {
                TableCell cell = ce.getValue();
                cell.setRowindex(newRow);
                // sort words LTR/TTB
                if (cell.getWords() != null) {
                    cell.getWords().sort(Comparator
                            .comparing((Word w) -> Optional.ofNullable(w.getY1()).orElse(0f))
                            .thenComparing(w -> Optional.ofNullable(w.getX1()).orElse(0f)));
                }
                newMap.put(ce.getKey(), cell);
            }
            compacted.put(newRow++, newMap);
        }

        Table table = new Table();
        table.setPageNumber(pageNumber);
        table.setTotalRows(compacted.size());
        table.setTotalColumns(cols);
        table.setCells(compacted);
        table.setColType(new ArrayList<>());
        table.setTxnColType(new ArrayList<>());
        table.setColumnBoundaries(new ArrayList<>(colBounds));
        table.setX1(colBounds.get(0));
        table.setY1(rowBounds.get(nonEmptyRows.get(0)));
        table.setX2(colBounds.get(colBounds.size() - 1));
        table.setY2(rowBounds.get(nonEmptyRows.get(0)));
        table.setX3(colBounds.get(colBounds.size() - 1));
        table.setY3(rowBounds.get(nonEmptyRows.get(nonEmptyRows.size() - 1) + 1));
        table.setX4(colBounds.get(0));
        table.setY4(rowBounds.get(nonEmptyRows.get(nonEmptyRows.size() - 1) + 1));
        table.setBankTransactions(looksLikeTransactionTable(table));
        return table;
    }

    static boolean looksLikeTransactionTable(Table table) {
        if (table == null || table.getCells() == null || table.getTotalRows() == null || table.getTotalColumns() == null) {
            return false;
        }
        if (table.getTotalRows() < 2 || table.getTotalColumns() < 3) {
            return false;
        }
        int dateHits = 0;
        int amountHits = 0;
        Pattern amount = Pattern.compile(".*\\d{1,3}(,\\d{2,3})*(\\.\\d{1,2})?.*|.*\\d+\\.\\d{2}.*");
        for (Map<Integer, TableCell> row : table.getCells().values()) {
            String rowText = row.values().stream()
                    .map(TableCell::getContent)
                    .filter(Objects::nonNull)
                    .collect(Collectors.joining(" "));
            if (DATE_LIKE.matcher(rowText).matches()) {
                dateHits++;
            }
            if (amount.matcher(rowText).matches()) {
                amountHits++;
            }
        }
        return dateHits >= 1 && amountHits >= 1 && (dateHits + amountHits) >= 3;
    }

    static boolean isDateLike(String text) {
        return text != null && DATE_LIKE.matcher(text).matches();
    }

    private static int findBucket(List<Float> bounds, float value) {
        for (int i = 0; i < bounds.size() - 1; i++) {
            if (value >= bounds.get(i) - 0.01f && value <= bounds.get(i + 1) + 0.01f) {
                return i;
            }
        }
        return -1;
    }

    static float midpointX(Word word) {
        float x1 = Optional.ofNullable(word.getX1()).orElse(0f);
        float x2 = Optional.ofNullable(word.getX2()).orElse(x1);
        return (x1 + x2) / 2f;
    }

    static float midpointY(Word word) {
        float y1 = Optional.ofNullable(word.getY1()).orElse(0f);
        float y3 = Optional.ofNullable(word.getY3()).orElse(y1);
        return (y1 + y3) / 2f;
    }

    static List<Float> clusterPositions(List<Float> values, float tolerance) {
        if (values == null || values.isEmpty()) {
            return List.of();
        }
        List<Float> sorted = values.stream().sorted().collect(Collectors.toList());
        List<Float> clusters = new ArrayList<>();
        float sum = sorted.get(0);
        int count = 1;
        float anchor = sorted.get(0);
        for (int i = 1; i < sorted.size(); i++) {
            float v = sorted.get(i);
            if (Math.abs(v - anchor) <= tolerance) {
                sum += v;
                count++;
            } else {
                clusters.add(sum / count);
                sum = v;
                count = 1;
                anchor = v;
            }
        }
        clusters.add(sum / count);
        return clusters;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Reconstructs tables from explicit horizontal/vertical ruling lines (bordered grids).
 */
@Component
public class BorderedGridTableExtractor {

    private static final float LINE_TOL = 0.02f;

    public Table extract(int pageNumber, NativePdfGeometry.PageGeometry geometry, List<Word> words) {
        if (geometry == null || words == null || words.isEmpty()) {
            return null;
        }

        List<NativePdfGeometry.LineSegment> hLines = geometry.getLines().stream()
                .filter(l -> l.isHorizontal(LINE_TOL) && l.length() > 0.5f)
                .collect(Collectors.toList());
        List<NativePdfGeometry.LineSegment> vLines = geometry.getLines().stream()
                .filter(l -> l.isVertical(LINE_TOL) && l.length() > 0.3f)
                .collect(Collectors.toList());

        if (hLines.size() < 3 || vLines.size() < 3) {
            return null;
        }

        List<Float> yBounds = NativeTableBuilder.clusterPositions(
                hLines.stream().map(l -> (l.getY1() + l.getY2()) / 2f).collect(Collectors.toList()),
                0.03f
        );
        List<Float> xBounds = NativeTableBuilder.clusterPositions(
                vLines.stream().map(l -> (l.getX1() + l.getX2()) / 2f).collect(Collectors.toList()),
                0.03f
        );

        if (xBounds.size() < 4 || yBounds.size() < 3) {
            return null;
        }

        // Keep the densest contiguous grid region covering most words
        float minWordX = words.stream().map(NativeTableBuilder::midpointX).min(Float::compare).orElse(0f);
        float maxWordX = words.stream().map(NativeTableBuilder::midpointX).max(Float::compare).orElse(0f);
        float minWordY = words.stream().map(NativeTableBuilder::midpointY).min(Float::compare).orElse(0f);
        float maxWordY = words.stream().map(NativeTableBuilder::midpointY).max(Float::compare).orElse(0f);

        List<Float> filteredX = xBounds.stream()
                .filter(x -> x >= minWordX - 0.2f && x <= maxWordX + 0.2f)
                .sorted()
                .collect(Collectors.toCollection(ArrayList::new));
        List<Float> filteredY = yBounds.stream()
                .filter(y -> y >= minWordY - 0.2f && y <= maxWordY + 0.2f)
                .sorted()
                .collect(Collectors.toCollection(ArrayList::new));

        if (filteredX.size() < 4 || filteredY.size() < 3) {
            filteredX = new ArrayList<>(xBounds);
            filteredY = new ArrayList<>(yBounds);
            filteredX.sort(Comparator.naturalOrder());
            filteredY.sort(Comparator.naturalOrder());
        }

        // Expand outer bounds slightly to capture edge text
        if (!filteredX.isEmpty()) {
            filteredX.set(0, filteredX.get(0) - 0.02f);
            filteredX.set(filteredX.size() - 1, filteredX.get(filteredX.size() - 1) + 0.02f);
        }
        if (!filteredY.isEmpty()) {
            filteredY.set(0, filteredY.get(0) - 0.02f);
            filteredY.set(filteredY.size() - 1, filteredY.get(filteredY.size() - 1) + 0.02f);
        }

        return NativeTableBuilder.buildTable(pageNumber, filteredX, filteredY, words);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import org.springframework.stereotype.Component;

import java.util.*;
import java.util.stream.Collectors;

/**
 * Reconstructs tables using filled/stroked rectangular boxes as cell or row guides.
 */
@Component
public class BoxGuidedTableExtractor {

    public Table extract(int pageNumber, NativePdfGeometry.PageGeometry geometry, List<Word> words) {
        if (geometry == null || words == null || words.isEmpty()) {
            return null;
        }

        List<NativePdfGeometry.Rect> rects = geometry.getRectangles().stream()
                .filter(r -> r.width() > 0.15f && r.height() > 0.08f && r.width() < geometry.getPageWidthInches() * 0.98f)
                .sorted(Comparator.comparing(NativePdfGeometry.Rect::getY1).thenComparing(NativePdfGeometry.Rect::getX1))
                .collect(Collectors.toList());

        if (rects.size() < 4) {
            return extractFromHorizontalRules(pageNumber, geometry, words);
        }

        // Prefer larger boxes that look like table cells in a grid band
        List<NativePdfGeometry.Rect> cellLike = rects.stream()
                .filter(r -> r.height() < 0.6f && r.width() < geometry.getPageWidthInches() * 0.7f)
                .collect(Collectors.toList());

        if (cellLike.size() >= 6) {
            List<Float> xBounds = NativeTableBuilder.clusterPositions(
                    cellLike.stream()
                            .flatMap(r -> List.of(r.getX1(), r.getX2()).stream())
                            .collect(Collectors.toList()),
                    0.04f
            );
            List<Float> yBounds = NativeTableBuilder.clusterPositions(
                    cellLike.stream()
                            .flatMap(r -> List.of(r.getY1(), r.getY2()).stream())
                            .collect(Collectors.toList()),
                    0.035f
            );
            if (xBounds.size() >= 4 && yBounds.size() >= 3) {
                Table table = NativeTableBuilder.buildTable(pageNumber, xBounds, yBounds, words);
                if (table != null) {
                    return table;
                }
            }
        }

        // Fall back: use box top edges as row separators + word X histogram for columns
        List<Float> rowYs = NativeTableBuilder.clusterPositions(
                rects.stream().map(NativePdfGeometry.Rect::getY1).collect(Collectors.toList()),
                0.04f
        );
        if (rowYs.size() < 3) {
            return extractFromHorizontalRules(pageNumber, geometry, words);
        }

        List<Float> yBounds = new ArrayList<>(rowYs);
        float maxY = words.stream().map(NativeTableBuilder::midpointY).max(Float::compare).orElse(rowYs.get(rowYs.size() - 1) + 0.25f);
        if (yBounds.get(yBounds.size() - 1) < maxY) {
            yBounds.add(maxY + 0.05f);
        }

        List<Float> xBounds = columnBoundsFromWords(words);
        if (xBounds.size() < 4) {
            return null;
        }
        return NativeTableBuilder.buildTable(pageNumber, xBounds, yBounds, words);
    }

    private Table extractFromHorizontalRules(int pageNumber, NativePdfGeometry.PageGeometry geometry, List<Word> words) {
        List<Float> hYs = geometry.getLines().stream()
                .filter(l -> l.isHorizontal(0.02f) && l.length() > geometry.getPageWidthInches() * 0.35f)
                .map(l -> (l.getY1() + l.getY2()) / 2f)
                .collect(Collectors.toList());
        List<Float> yBounds = NativeTableBuilder.clusterPositions(hYs, 0.03f);
        if (yBounds.size() < 3) {
            return null;
        }
        List<Float> xBounds = columnBoundsFromWords(words);
        if (xBounds.size() < 4) {
            return null;
        }
        return NativeTableBuilder.buildTable(pageNumber, xBounds, yBounds, words);
    }

    private List<Float> columnBoundsFromWords(List<Word> words) {
        List<Float> starts = words.stream()
                .map(w -> Optional.ofNullable(w.getX1()).orElse(0f))
                .sorted()
                .collect(Collectors.toList());
        if (starts.isEmpty()) {
            return List.of();
        }

        // Histogram gaps between word starts
        List<Float> clusters = NativeTableBuilder.clusterPositions(starts, 0.12f);
        if (clusters.size() < 3) {
            return List.of();
        }

        float minX = starts.get(0) - 0.02f;
        float maxX = words.stream().map(w -> Optional.ofNullable(w.getX2()).orElse(w.getX1())).max(Float::compare).orElse(minX + 1f) + 0.02f;

        List<Float> bounds = new ArrayList<>();
        bounds.add(minX);
        for (int i = 0; i < clusters.size() - 1; i++) {
            bounds.add((clusters.get(i) + clusters.get(i + 1)) / 2f);
        }
        bounds.add(maxX);
        return bounds;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import org.springframework.stereotype.Component;

import java.util.*;
import java.util.stream.Collectors;

/**
 * Text-aligned extraction: cluster words into rows, select transaction-like rows,
 * and split columns via horizontal gaps / start-position clustering.
 */
@Component
public class TextAlignedRowSelectedTableExtractor {

    private static final float ROW_Y_TOL = 0.045f;

    public Table extract(int pageNumber, List<Word> words) {
        if (words == null || words.isEmpty()) {
            return null;
        }

        List<List<Word>> rows = clusterRows(words);
        if (rows.size() < 3) {
            return null;
        }

        // Select rows that look transactional (date-like) plus neighboring multi-field rows
        List<Integer> selected = new ArrayList<>();
        for (int i = 0; i < rows.size(); i++) {
            String text = rows.get(i).stream().map(Word::getContent).filter(Objects::nonNull).collect(Collectors.joining(" "));
            if (NativeTableBuilder.isDateLike(text) || looksLikeHeader(text) || countNumericTokens(rows.get(i)) >= 2) {
                selected.add(i);
            }
        }
        if (selected.isEmpty()) {
            // Keep densest contiguous block of rows with >= 3 words
            for (int i = 0; i < rows.size(); i++) {
                if (rows.get(i).size() >= 3) {
                    selected.add(i);
                }
            }
        }
        if (selected.size() < 2) {
            return null;
        }

        // Expand selection to include immediate continuation lines (description wraps)
        Set<Integer> expanded = new TreeSet<>(selected);
        for (Integer idx : selected) {
            if (idx + 1 < rows.size() && rows.get(idx + 1).size() <= 4 && !NativeTableBuilder.isDateLike(
                    rows.get(idx + 1).stream().map(Word::getContent).collect(Collectors.joining(" ")))) {
                expanded.add(idx + 1);
            }
            if (idx > 0 && rows.get(idx - 1).size() >= 3) {
                expanded.add(idx - 1);
            }
        }

        List<List<Word>> selectedRows = expanded.stream().map(rows::get).collect(Collectors.toList());
        List<Word> selectedWords = selectedRows.stream().flatMap(Collection::stream).collect(Collectors.toList());

        List<Float> xBounds = inferColumnBounds(selectedRows);
        if (xBounds.size() < 4) {
            return null;
        }

        List<Float> yBounds = new ArrayList<>();
        for (List<Word> row : selectedRows) {
            float minY = row.stream().map(w -> Optional.ofNullable(w.getY1()).orElse(0f)).min(Float::compare).orElse(0f);
            yBounds.add(minY - 0.01f);
        }
        List<Word> last = selectedRows.get(selectedRows.size() - 1);
        float lastBottom = last.stream().map(w -> Optional.ofNullable(w.getY3()).orElse(w.getY1())).max(Float::compare).orElse(yBounds.get(yBounds.size() - 1) + 0.2f);
        yBounds.add(lastBottom + 0.02f);
        yBounds = NativeTableBuilder.clusterPositions(yBounds, 0.02f);
        if (yBounds.size() < 3) {
            return null;
        }

        return NativeTableBuilder.buildTable(pageNumber, xBounds, yBounds, selectedWords);
    }

    private boolean looksLikeHeader(String text) {
        if (text == null) {
            return false;
        }
        String t = text.toLowerCase(Locale.ROOT);
        return (t.contains("date") && (t.contains("balance") || t.contains("debit") || t.contains("credit") || t.contains("amount") || t.contains("particular")))
                || (t.contains("txn") && t.contains("date"))
                || (t.contains("value") && t.contains("date"));
    }

    private int countNumericTokens(List<Word> row) {
        int n = 0;
        for (Word w : row) {
            if (w.getContent() != null && w.getContent().matches(".*\\d.*")) {
                n++;
            }
        }
        return n;
    }

    private List<List<Word>> clusterRows(List<Word> words) {
        List<Word> sorted = words.stream()
                .sorted(Comparator.comparing(NativeTableBuilder::midpointY).thenComparing(NativeTableBuilder::midpointX))
                .collect(Collectors.toList());
        List<List<Word>> rows = new ArrayList<>();
        List<Word> current = new ArrayList<>();
        float currentY = Float.NaN;
        for (Word w : sorted) {
            float y = NativeTableBuilder.midpointY(w);
            if (current.isEmpty()) {
                current.add(w);
                currentY = y;
            } else if (Math.abs(y - currentY) <= ROW_Y_TOL) {
                current.add(w);
                currentY = (currentY * (current.size() - 1) + y) / current.size();
            } else {
                current.sort(Comparator.comparing(NativeTableBuilder::midpointX));
                rows.add(current);
                current = new ArrayList<>();
                current.add(w);
                currentY = y;
            }
        }
        if (!current.isEmpty()) {
            current.sort(Comparator.comparing(NativeTableBuilder::midpointX));
            rows.add(current);
        }
        return rows;
    }

    private List<Float> inferColumnBounds(List<List<Word>> rows) {
        // Use rows with many tokens as column anchors
        List<List<Word>> richRows = rows.stream().filter(r -> r.size() >= 3).collect(Collectors.toList());
        if (richRows.isEmpty()) {
            richRows = rows;
        }

        List<Float> starts = richRows.stream()
                .flatMap(Collection::stream)
                .map(w -> Optional.ofNullable(w.getX1()).orElse(0f))
                .collect(Collectors.toList());
        List<Float> clusters = NativeTableBuilder.clusterPositions(starts, 0.15f);
        if (clusters.size() < 3) {
            // Gap-based split on the densest row
            List<Word> densest = richRows.stream().max(Comparator.comparingInt(List::size)).orElse(List.of());
            if (densest.size() < 3) {
                return List.of();
            }
            clusters = densest.stream().map(w -> Optional.ofNullable(w.getX1()).orElse(0f)).sorted().collect(Collectors.toList());
        }

        float minX = starts.stream().min(Float::compare).orElse(0f) - 0.02f;
        float maxX = richRows.stream().flatMap(Collection::stream)
                .map(w -> Optional.ofNullable(w.getX2()).orElse(w.getX1())).max(Float::compare).orElse(minX + 1f) + 0.02f;

        List<Float> bounds = new ArrayList<>();
        bounds.add(minX);
        for (int i = 0; i < clusters.size() - 1; i++) {
            bounds.add((clusters.get(i) + clusters.get(i + 1)) / 2f);
        }
        bounds.add(maxX);
        // Deduplicate nearly equal bounds
        return NativeTableBuilder.clusterPositions(bounds, 0.03f);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.springframework.stereotype.Component;

import java.io.File;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Selects a native table policy for supported bank-format families in the fixture corpus.
 * Falls back to geometry probing when bank is known but format varies.
 */
@Component
@RequiredArgsConstructor
@Slf4j
public class NativePolicySelector {

    /**
     * Bank families present in the repository statement fixture corpus that have
     * at least one layout successfully handled by a native policy.
     */
    private static final Set<String> SUPPORTED_BANKS = Set.of(
            "AHMEDNAGAR",
            "AXIS",
            "BANDHAN",
            "BOB",
            "CBI",
            "CITI",
            "DEUSTCHE",
            "FEDERAL",
            "GS_MAHANAGAR_CO_OP_BANK",
            "GS_Mahanagar_Co_Op_Bank",
            "HDFC",
            "ICICI",
            "IDBI",
            "IDFC",
            "INDIAN",
            "INDIAN_OVERSEAS",
            "INDUSIND",
            "KOTAK",
            "PNB",
            "RBL",
            "SBI",
            "STANDARD_CHARTERED",
            "SURYODAY_SMALL_FINANCE_BANK_LTD",
            "TJSB",
            "TJSB_BANK",
            "UNION",
            "YES"
    );

    public boolean isSupportedBank(String bankName) {
        if (bankName == null || bankName.isBlank()) {
            return false;
        }
        String normalized = normalize(bankName);
        return SUPPORTED_BANKS.stream().anyMatch(b -> normalize(b).equals(normalized));
    }

    public NativeTablePolicy select(String bankName, File pdfFile) {
        NativeLayoutFeatures features = probe(pdfFile);
        NativeTablePolicy fromGeometry = selectFromGeometry(features);
        NativeTablePolicy fromFamily = selectFromBankFamily(bankName);

        // Prefer geometry when it is decisive; otherwise bank family default.
        if (features.getHorizontalLines() >= 20 && features.getVerticalLines() >= 10) {
            return NativeTablePolicy.BORDERED_GRID;
        }
        if (features.getRectangles() >= 40) {
            return NativeTablePolicy.BOX_GUIDED;
        }
        if (fromFamily != null) {
            return fromFamily;
        }
        return fromGeometry;
    }

    public NativeLayoutFeatures probe(File pdfFile) {
        NativeLayoutFeatures.NativeLayoutFeaturesBuilder builder = NativeLayoutFeatures.builder()
                .electronic(false)
                .horizontalLines(0)
                .verticalLines(0)
                .rectangles(0)
                .strokeOps(0)
                .fillOps(0)
                .wordCount(0);
        if (pdfFile == null || !pdfFile.exists()) {
            return builder.build();
        }
        try (PDDocument document = Loader.loadPDF(pdfFile)) {
            if (document.getNumberOfPages() == 0) {
                return builder.build();
            }
            // Probe first page (and second when available) for layout family.
            int pagesToProbe = Math.min(2, document.getNumberOfPages());
            int h = 0, v = 0, r = 0, s = 0, f = 0;
            for (int i = 0; i < pagesToProbe; i++) {
                PDPage page = document.getPage(i);
                NativePdfGeometry.PageGeometry geometry = NativePdfGeometry.collect(page);
                h += (int) geometry.getLines().stream().filter(l -> l.isHorizontal(0.02f)).count();
                v += (int) geometry.getLines().stream().filter(l -> l.isVertical(0.02f)).count();
                r += geometry.getRectangles().size();
                s += geometry.getStrokeOps();
                f += geometry.getFillOps();
            }
            builder.horizontalLines(h)
                    .verticalLines(v)
                    .rectangles(r)
                    .strokeOps(s)
                    .fillOps(f)
                    .electronic(true);
        } catch (Exception e) {
            log.debug("Native layout probe failed for {}: {}", pdfFile.getName(), e.getMessage());
        }
        return builder.build();
    }

    private NativeTablePolicy selectFromGeometry(NativeLayoutFeatures features) {
        if (features.getHorizontalLines() >= 15 && features.getVerticalLines() >= 8) {
            return NativeTablePolicy.BORDERED_GRID;
        }
        if (features.getRectangles() >= 20 || (features.getHorizontalLines() >= 8 && features.getVerticalLines() < 5)) {
            return NativeTablePolicy.BOX_GUIDED;
        }
        return NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED;
    }

    private NativeTablePolicy selectFromBankFamily(String bankName) {
        if (bankName == null) {
            return null;
        }
        String b = normalize(bankName);
        // Bordered-grid heavy families
        if (List.of("PNB", "BOB", "BANDHAN", "IDBI", "IDFC", "SURYODAY_SMALL_FINANCE_BANK_LTD",
                "TJSB", "TJSB_BANK", "STANDARD_CHARTERED").contains(b)) {
            return NativeTablePolicy.BORDERED_GRID;
        }
        // Box / shaded-row families
        if (List.of("HDFC", "ICICI", "SBI", "AXIS", "AHMEDNAGAR", "FEDERAL", "INDIAN",
                "INDIAN_OVERSEAS", "RBL", "YES", "DEUSTCHE", "CITI").contains(b)) {
            return NativeTablePolicy.BOX_GUIDED;
        }
        // Text-aligned families
        if (List.of("CBI", "KOTAK", "INDUSIND", "UNION", "GS_MAHANAGAR_CO_OP_BANK").contains(b)) {
            return NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED;
        }
        return null;
    }

    private String normalize(String bank) {
        return bank.trim().toUpperCase(Locale.ROOT).replace(' ', '_');
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.springframework.stereotype.Service;

import java.io.File;
import java.io.IOException;
import java.util.*;

/**
 * Offline native transaction-table extraction for electronic PDFs.
 * Produces DocumentExtractionResult tables compatible with downstream analysis.
 */
@Service
@RequiredArgsConstructor
@Slf4j
public class NativeTransactionTableExtractionService {

    private final NativeWordExtractor nativeWordExtractor;
    private final NativePolicySelector nativePolicySelector;
    private final BorderedGridTableExtractor borderedGridTableExtractor;
    private final BoxGuidedTableExtractor boxGuidedTableExtractor;
    private final TextAlignedRowSelectedTableExtractor textAlignedRowSelectedTableExtractor;

    public Optional<DocumentExtractionResult> tryExtract(File pdfFile, String bankName) {
        if (pdfFile == null || !pdfFile.exists()) {
            return Optional.empty();
        }
        if (!nativePolicySelector.isSupportedBank(bankName) && bankName != null && !bankName.isBlank()) {
            // Unknown banks still get a geometry-based attempt only when explicitly requested;
            // orchestration decides whether to call this service.
        }

        NativeTablePolicy primary = nativePolicySelector.select(bankName, pdfFile);
        try {
            Optional<DocumentExtractionResult> result = extractWithPolicy(pdfFile, primary);
            if (result.isPresent() && isSuccessful(result.get())) {
                result.get().setExtractionSource(ExtractionSource.NATIVE);
                result.get().setNativeTablePolicy(primary.name());
                return result;
            }

            // Try remaining policies as ordered fallbacks within native path
            for (NativeTablePolicy policy : orderedFallbacks(primary)) {
                Optional<DocumentExtractionResult> alt = extractWithPolicy(pdfFile, policy);
                if (alt.isPresent() && isSuccessful(alt.get())) {
                    alt.get().setExtractionSource(ExtractionSource.NATIVE);
                    alt.get().setNativeTablePolicy(policy.name());
                    return alt;
                }
            }
        } catch (Exception e) {
            log.info("Native extraction failed for bank={} file={}: {}", bankName, pdfFile.getName(), e.getMessage());
        }
        return Optional.empty();
    }

    public boolean isBankSupported(String bankName) {
        return nativePolicySelector.isSupportedBank(bankName);
    }

    private List<NativeTablePolicy> orderedFallbacks(NativeTablePolicy primary) {
        List<NativeTablePolicy> all = new ArrayList<>(List.of(
                NativeTablePolicy.BORDERED_GRID,
                NativeTablePolicy.BOX_GUIDED,
                NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED
        ));
        all.remove(primary);
        return all;
    }

    private Optional<DocumentExtractionResult> extractWithPolicy(File pdfFile, NativeTablePolicy policy) throws IOException {
        List<NativeWordExtractor.PageWords> pageWordsList = nativeWordExtractor.extract(pdfFile);
        if (pageWordsList.isEmpty()) {
            return Optional.empty();
        }

        // Reject likely scanned PDFs with almost no extractable text
        int totalWords = pageWordsList.stream().mapToInt(p -> p.getWords() == null ? 0 : p.getWords().size()).sum();
        if (totalWords < 20) {
            return Optional.empty();
        }

        DocumentExtractionResult result = new DocumentExtractionResult();
        Map<Integer, Page> pages = new LinkedHashMap<>();

        try (PDDocument document = Loader.loadPDF(pdfFile)) {
            for (NativeWordExtractor.PageWords pageWords : pageWordsList) {
                int pageNumber = pageWords.getPageNumber();
                PDPage pdPage = document.getPage(pageNumber - 1);
                NativePdfGeometry.PageGeometry geometry = NativePdfGeometry.collect(pdPage);

                Table table = switch (policy) {
                    case BORDERED_GRID -> borderedGridTableExtractor.extract(pageNumber, geometry, pageWords.getWords());
                    case BOX_GUIDED -> boxGuidedTableExtractor.extract(pageNumber, geometry, pageWords.getWords());
                    case TEXT_ALIGNED_ROW_SELECTED -> textAlignedRowSelectedTableExtractor.extract(pageNumber, pageWords.getWords());
                };

                Page page = new Page();
                page.setPageNumber(pageNumber);
                page.setWidth((double) pageWords.getWidth());
                page.setHeight((double) pageWords.getHeight());
                page.setWords(pageWords.getWords());
                page.setContent(buildContent(pageWords.getWords()));
                Map<Integer, Table> tables = new LinkedHashMap<>();
                if (table != null) {
                    tables.put(0, table);
                }
                page.setTables(tables);
                pages.put(pageNumber, page);
            }
        }

        result.setPages(pages);
        result.setNoOfPages(pages.size());
        assignWordIndices(result);
        return Optional.of(result);
    }

    private String buildContent(List<Word> words) {
        if (words == null) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (Word w : words) {
            if (w.getContent() != null) {
                if (sb.length() > 0) {
                    sb.append(' ');
                }
                sb.append(w.getContent());
            }
        }
        return sb.toString();
    }

    private boolean isSuccessful(DocumentExtractionResult result) {
        if (result == null || result.getPages() == null || result.getPages().isEmpty()) {
            return false;
        }
        int tables = 0;
        int txnLike = 0;
        int rows = 0;
        for (Page page : result.getPages().values()) {
            if (page.getTables() == null) {
                continue;
            }
            for (Table table : page.getTables().values()) {
                tables++;
                if (table.getTotalRows() != null) {
                    rows += table.getTotalRows();
                }
                if (table.getIsTransactionTable() || NativeTableBuilder.looksLikeTransactionTable(table)) {
                    txnLike++;
                    table.setBankTransactions(true);
                }
            }
        }
        return tables > 0 && rows >= 3 && txnLike > 0;
    }

    private void assignWordIndices(DocumentExtractionResult result) {
        int currentWordIndex = 1;
        List<Integer> pageNumbers = new ArrayList<>(result.getPages().keySet());
        Collections.sort(pageNumbers);
        for (Integer pageNumber : pageNumbers) {
            Page page = result.getPages().get(pageNumber);
            if (page.getTables() == null) {
                continue;
            }
            List<Integer> tableIndices = new ArrayList<>(page.getTables().keySet());
            Collections.sort(tableIndices);
            for (Integer tableIndex : tableIndices) {
                Table table = page.getTables().get(tableIndex);
                if (table.getCells() == null) {
                    continue;
                }
                List<Integer> rowIndices = new ArrayList<>(table.getCells().keySet());
                Collections.sort(rowIndices);
                for (Integer rowIndex : rowIndices) {
                    Map<Integer, TableCell> row = table.getCells().get(rowIndex);
                    if (row == null) {
                        continue;
                    }
                    List<Integer> cellIndices = new ArrayList<>(row.keySet());
                    Collections.sort(cellIndices);
                    for (Integer cellIndex : cellIndices) {
                        TableCell cell = row.get(cellIndex);
                        if (cell.getWords() == null) {
                            continue;
                        }
                        for (Word word : cell.getWords()) {
                            word.setPageIndex(pageNumber);
                            word.setWordIndex(currentWordIndex++);
                        }
                    }
                }
            }
        }
    }
}

