package com.finboost.bank.statement.parser.service.document.extraction.azure;

import com.azure.ai.documentintelligence.models.AnalyzeResult;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.ExtractionSource;
import com.finboost.bank.statement.parser.service.document.extraction.DocumentExtractionService;
import com.finboost.bank.statement.parser.service.document.extraction.IBankSpecificParsingService;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTransactionTableExtractionService;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import lombok.extern.slf4j.Slf4j;

import java.io.IOException;
import java.util.Optional;

@Service
@Slf4j
public class AzureDocumentExtractionServiceImpl implements DocumentExtractionService {

    private AzureDocumentIntelligenceProcessor azureDocumentIntelligenceProcessor;
    private AzureDocumentIntelligenceResponseMapper azureDocumentIntelligenceResponseMapper;
    private HistogramColumnDetectionService histogramColumnDetectionService;
    private MeanShiftColumnDetectionService meanShiftColumnDetectionService;
    private AnalyzeDocuments analyzeDocuments;
    private EPdfCharacterExtractionService ePdfCharacterExtractionService;
    private IBankSpecificParsingService bankSpecificParsingService;
    private NativeTransactionTableExtractionService nativeTransactionTableExtractionService;

    @Autowired
    public void setAzureDocumentIntelligenceProcessor(AzureDocumentIntelligenceProcessor azureDocumentIntelligenceProcessor) {
        this.azureDocumentIntelligenceProcessor = azureDocumentIntelligenceProcessor;
    }

    @Autowired
    public void setAzureDocumentIntelligenceResponseMapper(AzureDocumentIntelligenceResponseMapper azureDocumentIntelligenceResponseMapper) {
        this.azureDocumentIntelligenceResponseMapper = azureDocumentIntelligenceResponseMapper;
    }

    @Autowired
    public void setHistogramColumnDetectionService(HistogramColumnDetectionService histogramColumnDetectionService) {
        this.histogramColumnDetectionService = histogramColumnDetectionService;
    }

    @Autowired
    public void setMeanShiftColumnDetectionService(MeanShiftColumnDetectionService meanShiftColumnDetectionService) {
        this.meanShiftColumnDetectionService = meanShiftColumnDetectionService;
    }

    @Autowired
    public void setAnalyzeDocuments(AnalyzeDocuments analyzeDocuments) {
        this.analyzeDocuments = analyzeDocuments;
    }

    @Autowired
    public void setEPdfCharacterExtractionService(EPdfCharacterExtractionService ePdfCharacterExtractionService) {
        this.ePdfCharacterExtractionService = ePdfCharacterExtractionService;
    }

    @Autowired
    public void setBankSpecificParsingService(IBankSpecificParsingService bankSpecificParsingService) {
        this.bankSpecificParsingService = bankSpecificParsingService;
    }

    @Autowired
    public void setNativeTransactionTableExtractionService(NativeTransactionTableExtractionService nativeTransactionTableExtractionService) {
        this.nativeTransactionTableExtractionService = nativeTransactionTableExtractionService;
    }

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        DocumentExtractionRequest documentExtractionRequest = new DocumentExtractionRequest();
        documentExtractionRequest.setStatementFile(bankStatementVO.getDecryptedFile());
        documentExtractionRequest.setBankName(bankStatementVO.getBank());
        try{
            documentExtractionRequest.setStatementFromDate(BankStatementProcessorImpl.parseDate(bankStatementVO.getBankAccountDetailsVO().getStatementFrom()));
        }catch (Exception e){
            log.warn("Failed to parse statement-from-date from date string {}", bankStatementVO.getBankAccountDetailsVO().getStatementFrom());
        }
        DocumentExtractionResult result = extractDocument(documentExtractionRequest);
        if (result != null) {
            bankStatementVO.setExtractionSource(result.getExtractionSource());
            bankStatementVO.setNativeTablePolicy(result.getNativeTablePolicy());
        }
        return result;
    }

    @Override
    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        boolean nativeAttempted = false;

        // Native offline path for supported bank-format families / electronic layouts.
        if (request.getStatementFile() != null
                && (request.getBankName() == null
                || request.getBankName().isBlank()
                || nativeTransactionTableExtractionService.isBankSupported(request.getBankName()))) {
            nativeAttempted = request.getBankName() != null && !request.getBankName().isBlank()
                    && nativeTransactionTableExtractionService.isBankSupported(request.getBankName());
            if (nativeAttempted || request.getBankName() == null || request.getBankName().isBlank()) {
                // Only auto-attempt native when bank is a known supported family.
                if (nativeAttempted) {
                    Optional<DocumentExtractionResult> nativeResult =
                            nativeTransactionTableExtractionService.tryExtract(request.getStatementFile(), request.getBankName());
                    if (nativeResult.isPresent()) {
                        DocumentExtractionResult result = nativeResult.get();
                        log.info("Native table extraction succeeded for bank={} policy={}",
                                request.getBankName(), result.getNativeTablePolicy());
                        return finalizeWithoutRemoteMl(result, request);
                    }
                    log.info("Native table extraction unsuccessful for bank={}; falling back to remote ML",
                            request.getBankName());
                }
            }
        }

        // Default / fallback: remote ML (Azure Document Intelligence)
        DocumentExtractionResult result = extractWithRemoteMl(request);
        if (nativeAttempted) {
            result.setExtractionSource(ExtractionSource.NATIVE_TO_ML_FALLBACK);
        } else {
            result.setExtractionSource(ExtractionSource.ML);
        }
        return result;
    }

    private DocumentExtractionResult finalizeWithoutRemoteMl(DocumentExtractionResult result,
                                                             DocumentExtractionRequest request) {
        try {
            boolean enhanced = ePdfCharacterExtractionService.enhanceDocumentWithCharacterInfo(result, request.getStatementFile());
            if (enhanced) {
                log.info("Successfully enhanced native document with character-level information");
            }
        } catch (Exception e) {
            log.warn("Failed to enhance native document with character-level information: {}", e.getMessage());
        }

        bankSpecificParsingService.identifyBankSpecificStatementProcess(result, request);
        if (result.isSkipFurtherProcessing()) {
            return result;
        }

        DocumentExtractionResult preProcessedResultByHeader = analyzeDocuments.preProcessForVerificationByHeader(result, 5);
        if (preProcessedResultByHeader != null && preProcessedResultByHeader.getPreProcessVerificationResult() != null) {
            result.setPreProcessVerificationResult(preProcessedResultByHeader.getPreProcessVerificationResult());
        } else {
            DocumentExtractionResult preprocessedResult = analyzeDocuments.preProcessForVerification(result, result.getNoOfPages());
            if (preprocessedResult != null && preprocessedResult.getPreProcessVerificationResult() != null) {
                result.setPreProcessVerificationResult(preprocessedResult.getPreProcessVerificationResult());
            }
        }
        analyzeDocuments.analyzeDocument(result, true, true, true);
        result.setExtractionSource(ExtractionSource.NATIVE);
        return result;
    }

    private DocumentExtractionResult extractWithRemoteMl(DocumentExtractionRequest request) throws IOException {
        AnalyzeResult analyzeResult = azureDocumentIntelligenceProcessor.processDocument(request.getStatementFile());
        DocumentExtractionResult result = azureDocumentIntelligenceResponseMapper.mapAnalyzeResultToDocument(analyzeResult);

        try {
            boolean enhanced = ePdfCharacterExtractionService.enhanceDocumentWithCharacterInfo(result, request.getStatementFile());
            if (enhanced) {
                log.info("Successfully enhanced document with character-level information");
            } else {
                log.info("Document could not be enhanced with character-level information (likely a scanned PDF)");
            }
        } catch (Exception e) {
            log.warn("Failed to enhance document with character-level information: {}", e.getMessage());
        }

        bankSpecificParsingService.identifyBankSpecificStatementProcess(result, request);

        if(result.isSkipFurtherProcessing()){
            return result;
        }

        DocumentExtractionResult preProcessedResultByHeader = analyzeDocuments.preProcessForVerificationByHeader(result,5);
        if(preProcessedResultByHeader != null && preProcessedResultByHeader.getPreProcessVerificationResult() != null) {
            result.setPreProcessVerificationResult(preProcessedResultByHeader.getPreProcessVerificationResult());
        }else {
            DocumentExtractionResult preprocessedResult = analyzeDocuments.preProcessForVerification(result, analyzeResult.getPages().size());
            if (preprocessedResult != null && preprocessedResult.getPreProcessVerificationResult() != null) {
                result.setPreProcessVerificationResult(preprocessedResult.getPreProcessVerificationResult());
            }
        }
        analyzeDocuments.analyzeDocument(result, true, true, true);
        return result;
    }
}

