private ExtractionSource resolveAccountExtractionSource(List<BankStatementVO> statements) {
    if (statements == null || statements.isEmpty()) {
        return ExtractionSource.ML;
    }
    boolean sawNative = false;
    boolean sawMl = false;
    boolean sawFallback = false;
    for (BankStatementVO statement : statements) {
        ExtractionSource source = statement.getExtractionSource();
        if (source == null && statement.getDocumentExtractionResult() != null) {
            source = statement.getDocumentExtractionResult().getExtractionSource();
        }
        if (source == null) {
            sawMl = true;
            continue;
        }
        switch (source) {
            case NATIVE -> sawNative = true;
            case NATIVE_TO_ML_FALLBACK -> sawFallback = true;
            case ML -> sawMl = true;
        }
    }
    if (sawFallback || (sawNative && sawMl)) {
        return ExtractionSource.NATIVE_TO_ML_FALLBACK;
    }
    if (sawNative) {
        return ExtractionSource.NATIVE;
    }
    return ExtractionSource.ML;
}

